import type { RoadSignColour } from "./roadSignColors";

/**
 * Symbol path registry for `WarningSign`. Each entry is a list of black glyph
 * paths (extracted from the matching reference sign artwork) drawn on top of
 * the sign's inset background, using the same coordinate space as
 * `warningSignShape.ts` (i.e. `WARNING_SIGN_VIEW_BOX` + `WARNING_SIGN_GROUP_TRANSFORM`).
 * Symbols made of more than one disjoint shape (e.g. roundabout arrows) use
 * multiple path strings instead of one compound path.
 *
 * Path data is extracted as-is from the reference artwork on Wikimedia
 * Commons (`Iceland_road_sign_<code>.svg`), only stripping fill colours
 * (supplied via the `WarningSign` component's `symbolColour` prop instead)
 * and, where the source file used a different `<g transform>` than
 * `WARNING_SIGN_GROUP_TRANSFORM`, translating the leading anchor point so
 * coordinates line up with the shared triangle shape.
 *
 * Most symbols are a single colour and use plain `d` strings, recoloured via
 * `symbolColour`. A few symbols (e.g. `TrafficLights`) have parts that are a
 * fixed, non-black colour in the reference artwork (the red/amber/green
 * lamps) — those use the `{ d, colour }` form instead, which always renders
 * in `colour` and ignores `symbolColour`. Only the plain black parts of a
 * multi-colour symbol are recolourable.
 *
 * Add one entry per additional warning sign symbol as new reference artwork
 * is stripped down.
 */
export type WarningSignSymbolPath = string | Readonly<{ d: string; colour: RoadSignColour }>;
export type WarningSignSymbol =
  | "CurveRight"
